def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    return np.where(bins >= item, -(bins % item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    target_leftover = item * 0.25
    return np.where(remaining_after >= 0, -np.abs(remaining_after - target_leftover), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    return np.where(remaining_after >= 0, -np.abs(remaining_after - item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, remaining_space, -np.inf)
